'use strict';
const E=window.TreasuryEngine,$=id=>document.getElementById(id);let plan=null,busy=false,provider=null;const storageKey='fual-treasury-pending-v1';
const message=(s,error=false)=>{$('status').textContent=s;$('status').className='status'+(error?' error':'');};
function pending(){try{return E.unpack(localStorage.getItem(storageKey)||'null');}catch{throw Error('Không đọc được giao dịch đang chờ. Kiểm tra ví trước khi tiếp tục.');}}
function savePending(x){localStorage.setItem(storageKey,E.pack(x));}
function clearPending(){localStorage.removeItem(storageKey);}
function buttons(){let waiting;try{waiting=!!pending();}catch{waiting=true;}$('send').disabled=busy||waiting||!plan;$('prepare').disabled=busy||waiting;$('refresh').disabled=busy;$('connect').disabled=busy;}
async function run(fn){if(busy)return;busy=true;buttons();try{await fn();}catch(e){message(e.message||'Không thể hoàn tất bước này.',true);}finally{busy=false;buttons();}}
function showSnapshot(s){$('cash').textContent=E.format(s.cash);$('asset').textContent=E.format(s.asset);$('native').textContent=E.format(s.native);$('weight').textContent='Tỷ trọng '+(s.weight/100).toFixed(2)+'%';$('actual').textContent='Hiện tại '+(s.weight/100).toFixed(2)+'%';$('bar').style.width=Math.min(100,s.weight/100)+'%';$('sync').textContent='Dữ liệu mới: '+new Date(s.now*1000).toLocaleString('vi-VN')+' · Testnet';}
function showPlan(p){plan=p;showSnapshot(p.snapshot);$('review').hidden=p.kind==='HOLD';$('decisionBadge').textContent=p.kind==='HOLD'?'GIỮ NGUYÊN':p.kind==='APPROVE'?'CẦN CẤP QUYỀN':'SẴN SÀNG DUYỆT';$('decisionTitle').textContent=p.kind==='HOLD'?'Chưa cần giao dịch.':p.kind==='APPROVE'?(p.approvalAmount===0n?'Đặt lại quyền cũ về 0.':'Cấp quyền đúng số lượng trước.'):p.buy?'Điều chỉnh thêm WBNB thử nghiệm.':'Điều chỉnh bớt WBNB thử nghiệm.';
 $('decisionText').textContent=p.kind==='HOLD'?p.reason:p.kind==='APPROVE'?'Quyền sử dụng token hiện chưa đủ. Bước này chỉ cấp quyền; sau khi xác nhận sẽ lập lại kế hoạch đổi token.':'Danh mục đang lệch mục tiêu. Giao dịch được mô phỏng; anh vẫn quyết định trong ví.';
 $('details').replaceChildren();if(p.kind!=='HOLD'){const pairs=[['Thao tác',p.kind==='APPROVE'?'Cấp quyền '+E.format(p.approvalAmount)+' '+(p.buy?'U':'WBNB'):'Đổi '+E.format(p.amount)+' '+(p.buy?'U':'WBNB')],['Nhận tối thiểu',p.kind==='SWAP'?E.format(p.minimum,18,12)+' '+(p.buy?'WBNB':'U'):'Chưa đổi token'],['Ví nhận','0xdcf6…FA709'],['Mạng','BNB Smart Chain Testnet (97)'],['Phí ước tính',E.format(p.cost,18,10)+' tBNB']];for(const [label,value]of pairs){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=value;$('details').append(dt,dd);}$('expiry').textContent='Kế hoạch đến '+new Date(p.expires*1000).toLocaleTimeString('vi-VN')+'. Nếu hết hạn, bấm lập kế hoạch để tự điền lại.';}}
async function connect(){provider=window.ethereum;if(!provider)throw Error('Chưa thấy ví. Mở đường dẫn này trong Binance Wallet → Khám phá.');if(BigInt(await provider.request({method:'eth_chainId'}))!==97n){message('Anh xác nhận chuyển sang BNB Testnet trong ví. Bước này không gửi giao dịch.');try{await provider.request({method:'wallet_switchEthereumChain',params:[{chainId:'0x61'}]});}catch(e){if(e.code===4902){await provider.request({method:'wallet_addEthereumChain',params:[{chainId:'0x61',chainName:'BNB Smart Chain Testnet',nativeCurrency:{name:'Test BNB',symbol:'tBNB',decimals:18},rpcUrls:['https://bsc-testnet-dataseed.bnbchain.org'],blockExplorerUrls:['https://testnet.bscscan.com']}]});await provider.request({method:'wallet_switchEthereumChain',params:[{chainId:'0x61'}]});}else if(e.code===4001)throw Error('Anh đã hủy chuyển mạng. Chưa gửi giao dịch.');else throw Error('Ví chưa hỗ trợ chuyển mạng từ trang này: '+(e.message||e.code||'Không rõ lỗi')+'. Chưa gửi giao dịch.');}if(BigInt(await provider.request({method:'eth_chainId'}))!==97n)throw Error('Ví chưa chuyển sang BNB Testnet. Chưa gửi giao dịch.');}const accounts=await provider.request({method:'eth_requestAccounts'});if(!accounts.some(a=>a.toLowerCase()===E.C.wallet))throw Error('Hãy chọn đúng ví 0xdcf6…FA709.');$('walletState').textContent='Đã kết nối đúng ví · mọi giao dịch vẫn cần anh xác nhận.';$('connect').textContent='Đã kết nối';}
async function update(){const s=await E.snapshot();showSnapshot(s);return s;}
async function watch(record){if(!record.hash){$('recover').hidden=false;throw Error('Yêu cầu trước chưa trả mã giao dịch. Kiểm tra Binance Wallet trước khi gửi thêm.');}const end=Date.now()+60000;$('txLink').href='https://testnet.bscscan.com/tx/'+record.hash;$('txLink').hidden=false;while(Date.now()<end){const result=await E.verify(record.plan,record.hash);if(!result.pending){clearPending();$('recover').hidden=true;plan=null;$('review').hidden=true;message(result.kind==='SWAP'?'Đã xác minh đổi token thành công. Nhận '+E.format(result.output,18,12)+' '+(record.plan.buy?'WBNB':'U')+'. Phí '+E.format(result.fee,18,10)+' tBNB.':'Đã xác minh cấp quyền thành công. Bấm lập kế hoạch để chuẩn bị đổi token.');await update();return;}message('Đã gửi yêu cầu. Đang chờ xác nhận trên Testnet…');await new Promise(r=>setTimeout(r,2500));}message('Giao dịch còn chờ. Bấm cập nhật số dư để kiểm tra tiếp; không gửi lại.');}
async function send(){const execute=async()=>{if(pending())throw Error('Có giao dịch đang chờ; kiểm tra kết quả trước.');await connect();await E.validateForSend(plan);if(BigInt(await provider.request({method:'eth_chainId'}))!==97n)throw Error('Mạng trong ví đã thay đổi.');const accounts=await provider.request({method:'eth_accounts'});if(!accounts.some(a=>a.toLowerCase()===E.C.wallet))throw Error('Ví đã thay đổi.');const record={plan,hash:null,requestedAt:Date.now()};savePending(record);message('Kiểm tra yêu cầu trong Binance Wallet. Chỉ xác nhận nếu đúng số lượng và Testnet.');try{record.hash=await provider.request({method:'eth_sendTransaction',params:[plan.tx]});}catch(e){if(e.code===4001||e.code==='ACTION_REJECTED'){clearPending();message('Anh đã hủy yêu cầu trong ví. Chưa gửi giao dịch.');return;}$('recover').hidden=false;throw Error('Ví chưa trả kết quả chắc chắn. Kiểm tra lịch sử ví trước khi thử lại.');}savePending(record);await watch(record);};if(navigator.locks)await navigator.locks.request('fual-treasury-sign',{ifAvailable:true},async lock=>{if(!lock)throw Error('Một tab khác đang xử lý ví.');await execute();});else await execute();}
$('refresh').onclick=()=>run(async()=>{const p=pending();if(p)await watch(p);else{await update();message('Đã cập nhật số dư. Không có giao dịch được gửi.');}});
$('connect').onclick=()=>run(connect);
$('prepare').onclick=()=>run(async()=>{if(pending())throw Error('Kiểm tra giao dịch đang chờ trước.');showPlan(await E.prepare());message(plan.kind==='HOLD'?'Đã kiểm tra: giữ nguyên danh mục.':'Kế hoạch đã được điền tự động và mô phỏng. Anh đọc thông tin rồi duyệt trong ví.');});
$('send').onclick=()=>run(send);
$('recover').onclick=()=>{if(confirm('Anh đã kiểm tra lịch sử Binance Wallet và chắc chắn yêu cầu trước đã bị hủy, chưa có giao dịch được gửi?')){clearPending();$('recover').hidden=true;plan=null;$('review').hidden=true;buttons();message('Đã bỏ yêu cầu bị hủy. Bấm lập kế hoạch mới.');}};
window.addEventListener('storage',()=>buttons());buttons();try{const p=pending();if(p){message(p.hash?'Có giao dịch đang chờ kiểm tra. Bấm cập nhật số dư.':'Có yêu cầu ví chưa trả kết quả. Kiểm tra ví trước khi tiếp tục.');$('recover').hidden=!!p.hash;}}catch(e){message(e.message,true);}
